import { EMPTY_LAB_SUBMISSION, LAB_SUBMISSION_LABELS, LabSubmission, LabSubmissionStore } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

async function main(): Promise<void> {
  equal(EMPTY_LAB_SUBMISSION, { id: "", ownerId: "", assignmentId: "", summary: "", attachment: "" }, "empty constant");
  equal(LAB_SUBMISSION_LABELS, { one: "lab submission", many: "lab submissions" }, "labels");

  const first: LabSubmission = { id: "x", ownerId: "owner-1", assignmentId: "a-1", summary: "old", attachment: "old.txt" };
  const last: LabSubmission = { id: "x", ownerId: "owner-2", assignmentId: "a-2", summary: "last", attachment: "last.txt" };
  const store = new LabSubmissionStore([first, last]);
  (last as { summary: string }).summary = "caller mutation";
  equal(await store.findById("x"), { id: "x", ownerId: "owner-2", assignmentId: "a-2", summary: "last", attachment: "last.txt" }, "last duplicate wins and constructor copies");

  const found = await store.findById("x");
  assert(found !== undefined, "record should exist");
  (found as { summary: string }).summary = "returned mutation";
  assert((await store.findById("x"))?.summary === "last", "find result aliases stored record");
  assert(await store.findById("") === undefined, "empty ID is not found");
  assert(await store.findById("missing") === undefined, "missing ID is not found");

  const update: LabSubmission = { id: "x", ownerId: "replacement-owner", assignmentId: "replacement-assignment", summary: "new", attachment: "new.bin" };
  assert(await store.update(update), "existing update should return true");
  (update as { summary: string }).summary = "mutated later";
  equal(await store.findById("x"), { id: "x", ownerId: "owner-2", assignmentId: "a-2", summary: "new", attachment: "new.bin" }, "update changes only mutable fields and copies input");
  assert(!await store.update({ id: "none", ownerId: "o", assignmentId: "a", summary: "", attachment: "" }), "absent update should return false");
  assert(await store.update({ id: "x", ownerId: "ignored", assignmentId: "ignored", summary: "", attachment: "" }), "empty updated fields are valid");
  const emptied = await store.findById("x");
  assert(emptied?.summary === "" && emptied.attachment === "", "empty fields were stored");
  assert(new LabSubmissionStore() instanceof LabSubmissionStore, "omitted initial collection is valid");
}

main().catch(error => { throw error; });

